pub fn parse_args(raw_args: Vec<String>) -> Result<Args, String> {
    let mut args = Args::default();
    let mut i = 1usize;
    let mut positional: Vec<String> = Vec::new();
    let program = raw_args.get(0).cloned().unwrap_or_else(|| "hyperfine".to_string());

    // Check for --help or -h early
    for a in &raw_args[1..] {
        if a == "--help" || a == "-h" {
            print_help(&program);
            std::process::exit(0);
        }
        if a == "--version" || a == "-V" {
            println!("hyperfine 1.20.0");
            std::process::exit(0);
        }
    }

    while i < raw_args.len() {
        let arg = &raw_args[i];
        match arg.as_str() {
            "-w" | "--warmup" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--warmup")?;
                args.warmup = val.parse::<u64>().map_err(|_| format!("Invalid warmup value: {}", val))?;
            }
            "-m" | "--min-runs" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--min-runs")?;
                args.min_runs = Some(val.parse::<u64>().map_err(|_| format!("Invalid min-runs value: {}", val))?);
            }
            "-M" | "--max-runs" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--max-runs")?;
                args.max_runs = Some(val.parse::<u64>().map_err(|_| format!("Invalid max-runs value: {}", val))?);
            }
            "-r" | "--runs" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--runs")?;
                args.runs = Some(val.parse::<u64>().map_err(|_| format!("Invalid runs value: {}", val))?);
            }
            "-s" | "--setup" => {
                i += 1;
                args.setup = Some(get_required_arg(&raw_args, i, "--setup")?.to_string());
            }
            "--reference" => {
                i += 1;
                args.reference = Some(get_required_arg(&raw_args, i, "--reference")?.to_string());
            }
            "--reference-name" => {
                i += 1;
                args.reference_name = Some(get_required_arg(&raw_args, i, "--reference-name")?.to_string());
            }
            "-p" | "--prepare" => {
                i += 1;
                args.prepare.push(get_required_arg(&raw_args, i, "--prepare")?.to_string());
            }
            "-C" | "--conclude" => {
                i += 1;
                args.conclude.push(get_required_arg(&raw_args, i, "--conclude")?.to_string());
            }
            "-c" | "--cleanup" => {
                i += 1;
                args.cleanup = Some(get_required_arg(&raw_args, i, "--cleanup")?.to_string());
            }
            "-P" | "--parameter-scan" => {
                let var = get_required_arg(&raw_args, i + 1, "--parameter-scan VAR")?;
                let min_s = get_required_arg(&raw_args, i + 2, "--parameter-scan MIN")?;
                let max_s = get_required_arg(&raw_args, i + 3, "--parameter-scan MAX")?;
                let min = min_s.parse::<f64>().map_err(|_| format!("Invalid min value: {}", min_s))?;
                let max = max_s.parse::<f64>().map_err(|_| format!("Invalid max value: {}", max_s))?;
                args.parameter_scan = Some(ParameterScan { var: var.to_string(), min, max, step: None });
                i += 3;
            }
            "-D" | "--parameter-step-size" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--parameter-step-size")?;
                let delta = val.parse::<f64>().map_err(|_| format!("Invalid step size: {}", val))?;
                if let Some(ref mut scan) = args.parameter_scan {
                    scan.step = Some(delta);
                } else {
                    return Err("--parameter-step-size requires --parameter-scan".to_string());
                }
            }
            "-L" | "--parameter-list" => {
                let var = get_required_arg(&raw_args, i + 1, "--parameter-list VAR")?;
                let vals_s = get_required_arg(&raw_args, i + 2, "--parameter-list VALUES")?;
                let values: Vec<String> = vals_s.split(',').map(|s| s.to_string()).collect();
                args.parameter_lists.push(ParameterList { var: var.to_string(), values });
                i += 2;
            }
            "-S" | "--shell" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--shell")?;
                args.shell = parse_shell(val);
            }
            "-N" => {
                args.shell = Shell::None;
            }
            "-i" | "--ignore-failure" => {
                // Check if next arg is a value (not a flag)
                if i + 1 < raw_args.len() && !raw_args[i+1].starts_with('-') {
                    i += 1;
                    let val = &raw_args[i];
                    args.ignore_failure = parse_ignore_failure(val)?;
                } else {
                    args.ignore_failure = IgnoreFailure::AllNonZero;
                }
            }
            "--style" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--style")?;
                args.style = match val {
                    "auto" => OutputStyle::Auto,
                    "basic" => OutputStyle::Basic,
                    "full" => OutputStyle::Full,
                    "nocolor" => OutputStyle::NoColor,
                    "color" => OutputStyle::Color,
                    "none" => OutputStyle::None,
                    _ => return Err(format!("Invalid style: {}", val)),
                };
            }
            "--sort" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--sort")?;
                args.sort = match val {
                    "auto" => SortOrder::Auto,
                    "command" => SortOrder::Command,
                    "mean-time" => SortOrder::MeanTime,
                    _ => return Err(format!("Invalid sort: {}", val)),
                };
            }
            "-u" | "--time-unit" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--time-unit")?;
                args.time_unit = match val {
                    "second" => TimeUnit::Second,
                    "millisecond" => TimeUnit::Millisecond,
                    "microsecond" => TimeUnit::Microsecond,
                    _ => return Err(format!("Invalid time-unit: {}", val)),
                };
            }
            "--export-json" => {
                i += 1;
                args.export_json = Some(get_required_arg(&raw_args, i, "--export-json")?.to_string());
            }
            "--export-csv" => {
                i += 1;
                args.export_csv = Some(get_required_arg(&raw_args, i, "--export-csv")?.to_string());
            }
            "--export-markdown" => {
                i += 1;
                args.export_markdown = Some(get_required_arg(&raw_args, i, "--export-markdown")?.to_string());
            }
            "--export-asciidoc" => {
                i += 1;
                args.export_asciidoc = Some(get_required_arg(&raw_args, i, "--export-asciidoc")?.to_string());
            }
            "--export-orgmode" => {
                i += 1;
                args.export_orgmode = Some(get_required_arg(&raw_args, i, "--export-orgmode")?.to_string());
            }
            "--show-output" => {
                args.show_output = true;
            }
            "--output" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--output")?;
                args.output.push(parse_output_where(val));
            }
            "--input" => {
                i += 1;
                let val = get_required_arg(&raw_args, i, "--input")?;
                args.input = Some(parse_input_where(val));
            }
            "-n" | "--command-name" => {
                i += 1;
                args.command_names.push(get_required_arg(&raw_args, i, "--command-name")?.to_string());
            }
            _ => {
                // Handle --shell=none, --style=basic, -i=1,2, etc.
                if arg.starts_with("--shell=") {
                    let val = &arg["--shell=".len()..];
                    args.shell = parse_shell(val);
                } else if arg.starts_with("--style=") {
                    let val = &arg["--style=".len()..];
                    args.style = match val {
                        "auto" => OutputStyle::Auto,
                        "basic" => OutputStyle::Basic,
                        "full" => OutputStyle::Full,
                        "nocolor" => OutputStyle::NoColor,
                        "color" => OutputStyle::Color,
                        "none" => OutputStyle::None,
                        _ => return Err(format!("Invalid style: {}", val)),
                    };
                } else if arg.starts_with("--sort=") {
                    let val = &arg["--sort=".len()..];
                    args.sort = match val {
                        "auto" => SortOrder::Auto,
                        "command" => SortOrder::Command,
                        "mean-time" => SortOrder::MeanTime,
                        _ => return Err(format!("Invalid sort: {}", val)),
                    };
                } else if arg.starts_with("--time-unit=") {
                    let val = &arg["--time-unit=".len()..];
                    args.time_unit = match val {
                        "second" => TimeUnit::Second,
                        "millisecond" => TimeUnit::Millisecond,
                        "microsecond" => TimeUnit::Microsecond,
                        _ => return Err(format!("Invalid time-unit: {}", val)),
                    };
                } else if arg.starts_with("--ignore-failure=") || arg.starts_with("-i=") {
                    let val = if arg.starts_with("--ignore-failure=") {
                        &arg["--ignore-failure=".len()..]
                    } else {
                        &arg["-i=".len()..]
                    };
                    args.ignore_failure = parse_ignore_failure(val)?;
                } else if arg.starts_with("-") && arg.len() > 1 && !arg.starts_with("--") {
                    return Err(format!("unknown flag: {}", arg));
                } else {
                    positional.push(arg.clone());
                }
            }
        }
        i += 1;
    }

    // Validate conflicting options
    if args.show_output && args.style != OutputStyle::Auto {
        return Err("the argument '--style <TYPE>' cannot be used with '--show-output'".to_string());
    }

    args.commands = positional;

    Ok(args)
}

fn get_required_arg<'a>(args: &'a [String], i: usize, name: &str) -> Result<&'a str, String> {
    args.get(i)
        .map(|s| s.as_str())
        .ok_or_else(|| format!("Missing value for {}", name))
}

fn parse_shell(val: &str) -> Shell {
    match val {
        "none" => Shell::None,
        "default" => Shell::Default,
        _ => Shell::Custom(val.to_string()),
    }
}

fn parse_ignore_failure(val: &str) -> Result<IgnoreFailure, String> {
    if val == "all-non-zero" {
        return Ok(IgnoreFailure::AllNonZero);
    }
    // Try comma-separated exit codes
    let codes: Result<Vec<i32>, _> = val.split(',').map(|s| s.trim().parse::<i32>()).collect();
    match codes {
        Ok(c) => Ok(IgnoreFailure::ExitCodes(c)),
        Err(_) => Err(format!("Invalid ignore-failure value: {}", val)),
    }
}

fn parse_output_where(val: &str) -> OutputWhere {
    match val {
        "null" => OutputWhere::Null,
        "pipe" => OutputWhere::Pipe,
        "inherit" => OutputWhere::Inherit,
        _ => OutputWhere::File(val.to_string()),
    }
}

fn parse_input_where(val: &str) -> InputWhere {
    match val {
        "null" => InputWhere::Null,
        _ => InputWhere::File(val.to_string()),
    }
}

pub fn print_help(program: &str) {
    println!("A command-line benchmarking tool.");
