/// Statistical calculations for benchmark results

#[derive(Debug, Clone)]
pub struct Stats {
    pub mean: f64,
    pub stddev: f64,
    pub median: f64,
    pub min: f64,
    pub max: f64,
    pub user: f64,
    pub system: f64,
    pub times: Vec<f64>,
    pub memory_bytes: Vec<u64>,
    pub exit_codes: Vec<Option<i32>>,
}

impl Stats {
    pub fn new(
        times: Vec<f64>,
        user_times: Vec<f64>,
        system_times: Vec<f64>,
        memory_bytes: Vec<u64>,
        exit_codes: Vec<Option<i32>>,
    ) -> Self {
        let n = times.len();
        let mean = if n > 0 { times.iter().sum::<f64>() / n as f64 } else { 0.0 };
        let stddev = if n > 1 {
            let variance = times.iter().map(|t| (t - mean).powi(2)).sum::<f64>() / (n - 1) as f64;
            variance.sqrt()
        } else {
            0.0
        };

        let mut sorted = times.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let median = if n == 0 {
            0.0
        } else if n % 2 == 1 {
            sorted[n / 2]
        } else {
            (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
        };

        let min = sorted.first().copied().unwrap_or(0.0);
        let max = sorted.last().copied().unwrap_or(0.0);

        let user = if !user_times.is_empty() {
            user_times.iter().sum::<f64>() / user_times.len() as f64
        } else {
            0.0
        };

        let system = if !system_times.is_empty() {
            system_times.iter().sum::<f64>() / system_times.len() as f64
        } else {
            0.0
        };

        Stats { mean, stddev, median, min, max, user, system, times, memory_bytes, exit_codes }
    }

    pub fn has_outliers(&self) -> bool {
        let n = self.times.len();
        if n < 4 {
            return false;
        }

        let mut sorted = self.times.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let q1 = sorted[n / 4];
        let q3 = sorted[(3 * n) / 4];
        let iqr = q3 - q1;

        let lower = q1 - 3.0 * iqr;
        let upper = q3 + 3.0 * iqr;

        self.times.iter().any(|&t| t < lower || t > upper)
    }

    /// Check if first run is significantly slower than the rest
    pub fn first_run_significantly_slower(&self) -> Option<f64> {
        let n = self.times.len();
        if n < 2 {
            return None;
        }

        let first = self.times[0];
        let rest = &self.times[1..];

        let mut sorted_rest = rest.to_vec();
        sorted_rest.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let median_rest = if sorted_rest.is_empty() {
            return None;
        } else if sorted_rest.len() % 2 == 1 {
            sorted_rest[sorted_rest.len() / 2]
        } else {
            (sorted_rest[sorted_rest.len() / 2 - 1] + sorted_rest[sorted_rest.len() / 2]) / 2.0
        };

        // Only warn if the median of rest is meaningful
        if median_rest <= 0.0 {
            // Use mean instead
            let mean_rest: f64 = rest.iter().sum::<f64>() / rest.len() as f64;
            if mean_rest <= 0.0 || first <= 0.0 {
                return None;
            }
            if first > 2.0 * mean_rest {
                return Some(first);
            }
            return None;
        }

        // Threshold: first run is significantly slower if it's > 2x the median of rest
        if first > 2.0 * median_rest {
            Some(first)
        } else {
            None
        }
    }
}
