/// Timer and process execution utilities

use std::process::{Command, Stdio};
use std::time::Instant;
use std::io::Read;
use std::fs::File;

#[derive(Debug, Clone)]
pub struct RunResult {
    pub wall_time: f64,
    pub user_time: f64,
    pub system_time: f64,
    pub memory_bytes: u64,
    pub exit_code: Option<i32>,
}

/// Get resource usage for a completed process using /proc/[pid]/stat
fn get_rusage_from_proc(pid: u32) -> (f64, f64, u64) {
    // Try /proc/[pid]/status for memory
    let mem = read_proc_mem(pid);
    // User and system time from getrusage (we'll use wait4 approach)
    (0.0, 0.0, mem)
}

fn read_proc_mem(pid: u32) -> u64 {
    let path = format!("/proc/{}/status", pid);
    if let Ok(content) = std::fs::read_to_string(&path) {
        for line in content.lines() {
            if line.starts_with("VmRSS:") {
                let parts: Vec<&str> = line.split_whitespace().collect();
                if parts.len() >= 2 {
                    if let Ok(kb) = parts[1].parse::<u64>() {
                        return kb * 1024;
                    }
                }
            }
        }
    }
    0
}

/// Run a command and measure its execution time
pub fn time_command(
    cmd_str: &str,
    shell: &crate::args::Shell,
    env_vars: &[(String, String)],
    stdout_redirect: &crate::args::OutputWhere,
    stderr_redirect: &crate::args::OutputWhere,
    stdin_source: &crate::args::InputWhere,
    show_output: bool,
) -> Result<RunResult, String> {
    let mut cmd = build_command(cmd_str, shell);

    // Set environment variables
    for (k, v) in env_vars {
        cmd.env(k, v);
