/// Output formatting utilities

use crate::args::TimeUnit;

/// Determine the appropriate time unit for displaying a duration in seconds
pub fn determine_unit(seconds: f64) -> TimeUnit {
    if seconds >= 1.0 {
        TimeUnit::Second
    } else if seconds >= 0.001 {
        TimeUnit::Millisecond
    } else {
        TimeUnit::Microsecond
    }
}

/// Convert seconds to the given unit
pub fn to_unit(seconds: f64, unit: &TimeUnit) -> f64 {
    match unit {
        TimeUnit::Second => seconds,
        TimeUnit::Millisecond => seconds * 1000.0,
        TimeUnit::Microsecond => seconds * 1_000_000.0,
        TimeUnit::Auto => seconds, // shouldn't happen
    }
}

/// Get the unit suffix string
pub fn unit_suffix(unit: &TimeUnit) -> &'static str {
    match unit {
        TimeUnit::Second => "s",
        TimeUnit::Millisecond => "ms",
        TimeUnit::Microsecond => "µs",
        TimeUnit::Auto => "",
    }
}

/// Get decimal places for a time unit
pub fn unit_decimals(unit: &TimeUnit) -> usize {
    match unit {
        TimeUnit::Second => 3,
        TimeUnit::Millisecond => 1,
        TimeUnit::Microsecond => 1,
        TimeUnit::Auto => 3,
    }
}

/// Format a time value with appropriate precision
pub fn format_time_value(seconds: f64, unit: &TimeUnit) -> String {
    let val = to_unit(seconds, unit);
    let decimals = unit_decimals(unit);
    format!("{:.prec$}", val, prec = decimals)
}

/// Format a duration for display in the Time line
/// Returns the formatted section: "     100.7 ms ±   0.1 ms    [User: 0.4 ms, System: 0.3 ms]"
pub fn format_time_line(
    mean: f64,
    stddev: f64,
    user: f64,
    system: f64,
    unit: &TimeUnit,
    use_color: bool,
) -> String {
    let unit_str = unit_suffix(unit);
    let unit_len = unit_str.chars().count(); // display chars

    let mean_val = format_time_value(mean, unit);
    let stddev_val = format_time_value(stddev, unit);
    let user_val = format_time_value(user, unit);
    let sys_val = format_time_value(system, unit);

    // Field widths (display chars):
    // mean field = 12 - unit_len (right-aligned)
    // stddev field = 7 - unit_len (right-aligned, after "± ")
    let mean_field = (12usize).saturating_sub(unit_len);
    let stddev_field = (7usize).saturating_sub(unit_len);

    // Format: spaces + mean + " " + unit + " ± " + spaces + stddev + " " + unit + "    "
    let mean_formatted = format!("{:>width$}", mean_val, width = mean_field);
    let stddev_formatted = format!("{:>width$}", stddev_val, width = stddev_field);

    if use_color {
        format!(
            "{} {} \u{b1} {} {}    [User: {} {}, System: {} {}]",
            colored_bold_green(&mean_formatted),
            colored_green(unit_str),
            colored_green(&stddev_formatted),
            colored_green(unit_str),
            colored_blue(&user_val),
            colored_blue(unit_str),
            colored_blue(&sys_val),
            colored_blue(unit_str),
        )
    } else {
        format!(
            "{} {} \u{b1} {} {}    [User: {} {}, System: {} {}]",
            mean_formatted, unit_str, stddev_formatted, unit_str,
            user_val, unit_str, sys_val, unit_str
        )
    }
}

/// Format the Range line section
pub fn format_range_line(
    min: f64,
    max: f64,
    n: usize,
    unit: &TimeUnit,
    use_color: bool,
) -> String {
    let unit_str = unit_suffix(unit);
    let unit_len = unit_str.chars().count();

    let min_val = format_time_value(min, unit);
    let max_val = format_time_value(max, unit);

    // min field = 10 - unit_len, max field = same width
    let min_field = (10usize).saturating_sub(unit_len);
    let max_field = (7usize).saturating_sub(unit_len);

    let min_formatted = format!("{:>width$}", min_val, width = min_field);
    let max_formatted = format!("{:>width$}", max_val, width = max_field);

    if use_color {
        format!(
            "{} {} \u{2026} {} {}    {} runs",
            colored_cyan(&min_formatted),
            colored_cyan(unit_str),
            colored_magenta(&max_formatted),
            colored_magenta(unit_str),
            colored_dim(&n.to_string()),
        )
    } else {
        format!(
            "{} {} \u{2026} {} {}    {} runs",
            min_formatted, unit_str, max_formatted, unit_str, n
        )
    }
}

/// Format a time value with unit for compact display (user/sys in brackets)
pub fn format_compact_time(seconds: f64, unit: &TimeUnit) -> String {
    let val = format_time_value(seconds, unit);
    format!("{} {}", val, unit_suffix(unit))
}

