/// Shell calibration - measure shell startup overhead

use std::time::Instant;
use crate::args::Shell;
use crate::timer::{build_command, RunResult};
use std::process::Stdio;

/// Number of calibration runs for shell startup
const CALIBRATION_RUNS: usize = 200;

/// Calibrate shell startup time by running empty commands
pub fn calibrate_shell(shell: &Shell) -> f64 {
    match shell {
        Shell::None => 0.0,
        _ => {
            let mut times = Vec::with_capacity(CALIBRATION_RUNS);
            for _ in 0..CALIBRATION_RUNS {
                let start = Instant::now();
                let mut cmd = build_command("", shell);
                cmd.stdout(Stdio::null());
                cmd.stderr(Stdio::null());
                cmd.stdin(Stdio::null());
                if let Ok(mut child) = cmd.spawn() {
                    let _ = child.wait();
                }
                times.push(start.elapsed().as_secs_f64());
            }

            if times.is_empty() {
                return 0.0;
            }

            // Use median to avoid outliers
            times.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let n = times.len();
            let median = if n % 2 == 1 {
                times[n / 2]
            } else {
                (times[n / 2 - 1] + times[n / 2]) / 2.0
            };

            median.max(0.0)
        }
    }
}
