/// Progress bar and spinner for interactive output

use std::io::{self, Write};

/// Spinner frames (braille)
const SPINNER_FRAMES: &[&str] = &["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
const PROGRESS_FILL: char = '█';
const PROGRESS_EMPTY: char = '░';
const PROGRESS_WIDTH: usize = 32;

pub struct ProgressBar {
    spinner_idx: usize,
    is_tty: bool,
    last_len: usize,
}

impl ProgressBar {
    pub fn new(is_tty: bool) -> Self {
        ProgressBar {
            spinner_idx: 0,
            is_tty,
            last_len: 0,
        }
    }

    fn advance_spinner(&mut self) -> &'static str {
        let frame = SPINNER_FRAMES[self.spinner_idx % SPINNER_FRAMES.len()];
        self.spinner_idx += 1;
        frame
    }

    /// Clear the current line
    fn clear_line(&self) {
        if self.is_tty && self.last_len > 0 {
            print!("\r{}\r", " ".repeat(self.last_len + 10));
        }
    }

    /// Show warmup progress
    pub fn show_warmup_progress(&mut self, current: usize, total: usize) {
        if !self.is_tty {
            return;
        }

        let spinner = self.advance_spinner();
        let progress = if total > 0 { current as f64 / total as f64 } else { 0.0 };
        let filled = (progress * PROGRESS_WIDTH as f64) as usize;
        let empty = PROGRESS_WIDTH - filled.min(PROGRESS_WIDTH);

        let bar = format!("{}{}", 
            PROGRESS_FILL.to_string().repeat(filled),
            PROGRESS_EMPTY.to_string().repeat(empty));

        let remaining = total.saturating_sub(current);
        // Estimate ETA assuming uniform progress
        let eta_secs = 0u64; // we don't know the time per run here

        let line = format!(" {} Performing warmup runs         {} ETA 00:00:00",
            spinner, bar);

        self.clear_line();
        self.last_len = line.len();
        print!("{}", line);
        let _ = io::stdout().flush();
    }

    /// Show benchmark progress with current estimate
    pub fn show_benchmark_progress(
        &mut self,
        current: usize,
        total: usize,
        mean_estimate: Option<f64>,
        unit: &crate::args::TimeUnit,
    ) {
        if !self.is_tty {
            return;
