/// Export functionality for various formats

use crate::benchmark::BenchmarkResult;
use crate::args::TimeUnit;
use crate::format::{format_time_value, unit_suffix, determine_unit, to_unit};

/// Export results to JSON format
pub fn export_json(results: &[BenchmarkResult]) -> String {
    let mut out = String::new();
    out.push_str("{\n");
    out.push_str("  \"results\": [\n");

    for (i, r) in results.iter().enumerate() {
        out.push_str("    {\n");
        out.push_str(&format!("      \"command\": {:?},\n", r.display_name));
        out.push_str(&format!("      \"mean\": {:?},\n", r.stats.mean));
        out.push_str(&format!("      \"stddev\": {:?},\n", r.stats.stddev));
        out.push_str(&format!("      \"median\": {:?},\n", r.stats.median));
        out.push_str(&format!("      \"user\": {:?},\n", r.stats.user));
        out.push_str(&format!("      \"system\": {:?},\n", r.stats.system));
        out.push_str(&format!("      \"min\": {:?},\n", r.stats.min));
        out.push_str(&format!("      \"max\": {:?},\n", r.stats.max));

        // Times array
        out.push_str("      \"times\": [\n");
        for (j, t) in r.stats.times.iter().enumerate() {
            if j + 1 < r.stats.times.len() {
                out.push_str(&format!("        {:?},\n", t));
            } else {
                out.push_str(&format!("        {:?}\n", t));
            }
        }
        out.push_str("      ],\n");

        // Memory usage
        out.push_str("      \"memory_usage_byte\": [\n");
        for (j, m) in r.stats.memory_bytes.iter().enumerate() {
            if j + 1 < r.stats.memory_bytes.len() {
                out.push_str(&format!("        {},\n", m));
            } else {
                out.push_str(&format!("        {}\n", m));
            }
        }
        out.push_str("      ],\n");

        // Exit codes
        out.push_str("      \"exit_codes\": [\n");
        for (j, ec) in r.stats.exit_codes.iter().enumerate() {
            let ec_str = match ec {
                Some(code) => code.to_string(),
                None => "null".to_string(),
            };
            if j + 1 < r.stats.exit_codes.len() {
                out.push_str(&format!("        {},\n", ec_str));
            } else {
                out.push_str(&format!("        {}\n", ec_str));
            }
        }

        // Parameters (if any)
        if r.parameters.is_empty() {
            out.push_str("      ]\n");
        } else {
            out.push_str("      ],\n");
            out.push_str("      \"parameters\": {\n");
            let params: Vec<_> = r.parameters.iter().collect();
            for (j, (k, v)) in params.iter().enumerate() {
                if j + 1 < params.len() {
                    out.push_str(&format!("        {:?}: {:?},\n", k, v));
                } else {
                    out.push_str(&format!("        {:?}: {:?}\n", k, v));
                }
            }
            out.push_str("      }\n");
        }

        if i + 1 < results.len() {
            out.push_str("    },\n");
        } else {
            out.push_str("    }\n");
        }
    }

    out.push_str("  ]\n");
    out.push_str("}\n");
    out
}

/// Export results to CSV format (always in seconds)
pub fn export_csv(results: &[BenchmarkResult]) -> String {
    let mut out = String::new();
    out.push_str("command,mean,stddev,median,user,system,min,max\n");

    for r in results {
        out.push_str(&format!(
            "{},{},{},{},{},{},{},{}\n",
            r.display_name,
            r.stats.mean,
            r.stats.stddev,
            r.stats.median,
            r.stats.user,
            r.stats.system,
            r.stats.min,
            r.stats.max,
        ));
    }

    out
}

/// Get relative ratio for a result compared to the fastest (or reference)
fn get_relative(result: &BenchmarkResult, reference_mean: f64, reference_stddev: f64) -> (f64, f64) {
    let ratio = result.stats.mean / reference_mean;
    // Error propagation for ratio
    let sigma = ratio * ((result.stats.stddev / result.stats.mean).powi(2) + 
                         (reference_stddev / reference_mean).powi(2)).sqrt();
    (ratio, sigma)
}

/// Get the appropriate unit for export tables
fn get_export_unit(results: &[BenchmarkResult], time_unit: &TimeUnit) -> TimeUnit {
    match time_unit {
        TimeUnit::Auto => {
            // Use the mean of the fastest command to determine unit
            if let Some(min_mean) = results.iter().map(|r| r.stats.mean).reduce(f64::min) {
                determine_unit(min_mean)
            } else {
                TimeUnit::Second
            }
        }
        other => other.clone(),
    }
}

/// Export to Markdown table format
pub fn export_markdown(
    results: &[BenchmarkResult],
    time_unit: &TimeUnit,
    sort: &crate::args::SortOrder,
    reference_idx: Option<usize>,
) -> String {
    let unit = get_export_unit(results, time_unit);
    let unit_str = unit_suffix(&unit);
    let decimals = crate::format::unit_decimals(&unit);

    // Determine sort order for table
    let indices: Vec<usize> = get_sorted_indices(results, sort);

    // Find reference for relative column
    let ref_idx = reference_idx.unwrap_or_else(|| {
        results.iter().enumerate()
            .min_by(|(_, a), (_, b)| a.stats.mean.partial_cmp(&b.stats.mean).unwrap())
            .map(|(i, _)| i)
            .unwrap_or(0)
    });

    let ref_mean = results[ref_idx].stats.mean;
    let ref_stddev = results[ref_idx].stats.stddev;

    let mut out = String::new();
    out.push_str(&format!("| Command | Mean [{}] | Min [{}] | Max [{}] | Relative |\n", unit_str, unit_str, unit_str));
    out.push_str("|:---|---:|---:|---:|---:|\n");

    for i in indices {
        let r = &results[i];
        let mean_val = to_unit(r.stats.mean, &unit);
        let stddev_val = to_unit(r.stats.stddev, &unit);
        let min_val = to_unit(r.stats.min, &unit);
        let max_val = to_unit(r.stats.max, &unit);

        let relative = if i == ref_idx {
            "1.00".to_string()
        } else {
            let (ratio, sigma) = get_relative(r, ref_mean, ref_stddev);
            format!("{:.2} ± {:.2}", ratio, sigma)
        };

        out.push_str(&format!(
            "| `{}` | {:.prec$} ± {:.prec$} | {:.prec$} | {:.prec$} | {} |\n",
            r.display_name,
            mean_val, stddev_val,
            min_val, max_val,
            relative,
            prec = decimals,
        ));
    }

    out
}

/// Export to AsciiDoc table format
pub fn export_asciidoc(
    results: &[BenchmarkResult],
    time_unit: &TimeUnit,
    sort: &crate::args::SortOrder,
    reference_idx: Option<usize>,
) -> String {
    let unit = get_export_unit(results, time_unit);
    let unit_str = unit_suffix(&unit);
    let decimals = crate::format::unit_decimals(&unit);

    let indices = get_sorted_indices(results, sort);

    let ref_idx = reference_idx.unwrap_or_else(|| {
        results.iter().enumerate()
            .min_by(|(_, a), (_, b)| a.stats.mean.partial_cmp(&b.stats.mean).unwrap())
