            .unwrap_or(0)
    });

    let ref_mean = results[ref_idx].stats.mean;
    let ref_stddev = results[ref_idx].stats.stddev;

    let mut out = String::new();
    out.push_str("[cols=\"<,>,>,>,>\"]\n");
    out.push_str("|===\n");
    out.push_str(&format!("| Command \n| Mean [{}] \n| Min [{}] \n| Max [{}] \n| Relative \n\n", unit_str, unit_str, unit_str));

    for i in indices {
        let r = &results[i];
        let mean_val = to_unit(r.stats.mean, &unit);
        let stddev_val = to_unit(r.stats.stddev, &unit);
        let min_val = to_unit(r.stats.min, &unit);
        let max_val = to_unit(r.stats.max, &unit);

        let relative = if i == ref_idx {
            "1.00".to_string()
        } else {
            let (ratio, sigma) = get_relative(r, ref_mean, ref_stddev);
            format!("{:.2} ± {:.2}", ratio, sigma)
        };

        out.push_str(&format!(
            "| `{}` \n| {:.prec$} ± {:.prec$} \n| {:.prec$} \n| {:.prec$} \n| {} \n\n",
            r.display_name,
            mean_val, stddev_val,
            min_val, max_val,
            relative,
            prec = decimals,
        ));
    }

    out.push_str("|===\n");
    out
}

