fn get_sorted_indices(results: &[BenchmarkResult], sort: &crate::args::SortOrder) -> Vec<usize> {
    let mut indices: Vec<usize> = (0..results.len()).collect();
    match sort {
        crate::args::SortOrder::Auto | crate::args::SortOrder::Command => {
            // Keep original order
        }
        crate::args::SortOrder::MeanTime => {
            indices.sort_by(|&a, &b| {
                results[a].stats.mean.partial_cmp(&results[b].stats.mean).unwrap()
            });
        }
    }
    indices
}
