/// Core benchmark execution logic

use std::collections::HashMap;
use crate::args::*;
use crate::stats::Stats;
use crate::timer::{RunResult, time_command, build_command};
use crate::format::*;
use crate::progress::ProgressBar;
use std::process::Stdio;

pub const DEFAULT_MIN_RUNS: u64 = 10;
pub const TARGET_TIME_SECS: f64 = 3.0;
pub const FAST_CMD_THRESHOLD_SECS: f64 = 0.005; // 5ms

#[derive(Debug, Clone)]
pub struct BenchmarkResult {
    pub display_name: String,
    pub command: String,
    pub stats: Stats,
    pub parameters: HashMap<String, String>,
}

#[derive(Debug)]
pub struct BenchmarkSpec {
    pub command: String,
    pub display_name: String,
    pub prepare: Option<String>,
    pub conclude: Option<String>,
    pub parameters: HashMap<String, String>,
    pub output_where: OutputWhere,
    pub input_where: InputWhere,
}

pub fn run_benchmark(
    spec: &BenchmarkSpec,
    global_args: &Args,
    bench_index: usize,
    total_benches: usize,
    shell_overhead: f64,
    is_tty: bool,
    use_color: bool,
    use_progress: bool,
) -> Result<BenchmarkResult, String> {
    let style_is_none = matches!(global_args.style, OutputStyle::None);

    // Print benchmark header
    if !style_is_none {
        let bench_header = if use_color {
            format!("{}{}{}:{} {}", 
                "\x1b[1m", 
                format!("Benchmark {}", bench_index + 1),
                "\x1b[0m",
                "\x1b[1m",
                format!("{}\x1b[0m", spec.display_name))
        } else {
            format!("Benchmark {}: {}", bench_index + 1, spec.display_name)
        };
        println!("{}", bench_header);
    }

    // Run setup command (once per benchmark)
    if let Some(setup) = &global_args.setup {
        run_helper_command(setup, &global_args.shell)?;
    }

    // Show output mode
    let show_output = global_args.show_output || 
        matches!(spec.output_where, OutputWhere::Inherit);

    // Determine stdin source
    let stdin_src = global_args.input.clone().unwrap_or(InputWhere::Null);

    // Warmup runs
    if global_args.warmup > 0 && use_progress {
        // Show warmup progress
    }

    for warmup_idx in 0..global_args.warmup {
        if use_progress && !style_is_none {
            // Show warmup progress bar
            let progress = warmup_idx as f64 / global_args.warmup as f64;
            let filled = (progress * 32.0) as usize;
            let empty = 32 - filled;
            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));
            let remaining = global_args.warmup - warmup_idx;
            let spinner = get_spinner(warmup_idx as usize);
            eprint!("\r {} Performing warmup runs         {} ETA 00:00:{:02}",
                spinner, bar, remaining);
            let _ = std::io::Write::flush(&mut std::io::stderr());
        }

        if let Some(prep) = &spec.prepare {
            run_helper_command(prep, &global_args.shell)?;
        }

        let _ = time_command(
            &spec.command,
            &global_args.shell,
            &[("HYPERFINE_ITERATION".to_string(), warmup_idx.to_string())],
            &spec.output_where,
            &spec.output_where,
            &stdin_src,
            show_output,
        );

        if let Some(conclude) = &spec.conclude {
            run_helper_command(conclude, &global_args.shell)?;
        }
    }

    if global_args.warmup > 0 && use_progress && !style_is_none {
        // Clear warmup progress
        eprint!("\r{}\r", " ".repeat(80));
        let _ = std::io::Write::flush(&mut std::io::stderr());
    }

    // Determine number of runs
    let num_runs = determine_run_count(
        &spec.command,
        &global_args.shell,
        &spec.output_where,
        &stdin_src,
        global_args.runs,
        global_args.min_runs,
        global_args.max_runs,
        shell_overhead,
    )?;

    // Execute benchmark runs
    let mut times: Vec<f64> = Vec::new();
    let mut user_times: Vec<f64> = Vec::new();
    let mut system_times: Vec<f64> = Vec::new();
    let mut memory_bytes: Vec<u64> = Vec::new();
    let mut exit_codes: Vec<Option<i32>> = Vec::new();

    let mut mean_estimate: Option<f64> = None;

    for run_idx in 0..num_runs {
        // Show progress bar
        if use_progress && !style_is_none {
            let progress = run_idx as f64 / num_runs as f64;
            let filled = (progress * 32.0) as usize;
            let empty = 32 - filled;
            let bar = format!("{}{}", "█".repeat(filled), "░".repeat(empty));

            let unit = match &global_args.time_unit {
                TimeUnit::Auto => {
                    if let Some(m) = mean_estimate {
                        determine_unit(m)
                    } else {
                        TimeUnit::Millisecond
                    }
                }
                u => u.clone(),
            };

            let estimate_str = if let Some(mean) = mean_estimate {
                let v = format_compact_time(mean, &unit);
                format!("Current estimate: {:16}", v)
            } else {
                format!("{:32}", "")
            };

            let remaining = num_runs - run_idx;
            let eta_secs = if let Some(mean) = mean_estimate {
                (mean * remaining as f64) as u64
            } else {
                0
            };

            let spinner = get_spinner(run_idx as usize);
            eprint!("\r {} {} {} ETA {:02}:{:02}:{:02}",
                spinner, estimate_str, bar,
                eta_secs / 3600, (eta_secs % 3600) / 60, eta_secs % 60);
            let _ = std::io::Write::flush(&mut std::io::stderr());
        }

        // Run prepare command
        if let Some(prep) = &spec.prepare {
            run_helper_command(prep, &global_args.shell)?;
        }

        // Time the actual command
        let result = time_command(
            &spec.command,
            &global_args.shell,
            &[("HYPERFINE_ITERATION".to_string(), run_idx.to_string())],
            &spec.output_where,
            &spec.output_where,
            &stdin_src,
            show_output,
        )?;

        // Check exit code
        let exit_code = result.exit_code;
        exit_codes.push(exit_code);

        // Check for failure on first run
        if run_idx == 0 {
            if let Some(code) = exit_code {
                if code != 0 {
                    let should_ignore = match &global_args.ignore_failure {
                        IgnoreFailure::None => false,
                        IgnoreFailure::AllNonZero => true,
                        IgnoreFailure::ExitCodes(codes) => codes.contains(&code),
                    };
                    if !should_ignore {
                        // Clear progress if needed
                        if use_progress && !style_is_none {
                            eprint!("\r{}\r", " ".repeat(80));
                        }
                        // Run conclude/cleanup before returning error
                        if let Some(conclude) = &spec.conclude {
                            let _ = run_helper_command(conclude, &global_args.shell);
                        }
                        if let Some(cleanup) = &global_args.cleanup {
                            let _ = run_helper_command(cleanup, &global_args.shell);
                        }
                        return Err(format!(
                            "Command terminated with non-zero exit code {} in the first benchmark run. \
                             Use the '-i'/'--ignore-failure' option if you want to ignore this. \
                             Alternatively, use the '--show-output' option to debug what went wrong.",
                            code
                        ));
                    }
                }
            }
        }

        // Subtract shell overhead
        let adjusted_time = (result.wall_time - shell_overhead).max(0.0);
        times.push(adjusted_time);
        user_times.push(result.user_time);
        system_times.push(result.system_time);
        memory_bytes.push(result.memory_bytes);

        // Update mean estimate
        mean_estimate = Some(times.iter().sum::<f64>() / times.len() as f64);

        // Run conclude command
        if let Some(conclude) = &spec.conclude {
            run_helper_command(conclude, &global_args.shell)?;
        }
    }

    // Clear progress bar
    if use_progress && !style_is_none {
        eprint!("\r{}\r", " ".repeat(100));
        let _ = std::io::Write::flush(&mut std::io::stderr());
    }

    let stats = Stats::new(times, user_times, system_times, memory_bytes, exit_codes);

    // Run cleanup command
    if let Some(cleanup) = &global_args.cleanup {
        run_helper_command(cleanup, &global_args.shell)?;
    }

    // Print results
    if !style_is_none {
        print_benchmark_results(&stats, global_args, use_color);
    }

    Ok(BenchmarkResult {
        display_name: spec.display_name.clone(),
        command: spec.command.clone(),
        stats,
        parameters: spec.parameters.clone(),
    })
}

fn get_spinner(idx: usize) -> &'static str {
    const FRAMES: &[&str] = &["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
    FRAMES[idx % FRAMES.len()]
}

fn determine_run_count(
    command: &str,
    shell: &Shell,
    output_where: &OutputWhere,
    stdin_src: &InputWhere,
    fixed_runs: Option<u64>,
    min_runs: Option<u64>,
    max_runs: Option<u64>,
    shell_overhead: f64,
) -> Result<u64, String> {
    if let Some(runs) = fixed_runs {
        return Ok(runs);
    }

    let min = min_runs.unwrap_or(DEFAULT_MIN_RUNS);

    // Run one calibration measurement
    let calib_result = time_command(
        command,
        shell,
        &[("HYPERFINE_ITERATION".to_string(), "0".to_string())],
        output_where,
        output_where,
        stdin_src,
        false,
    )?;

    let calib_time = (calib_result.wall_time - shell_overhead).max(0.0);

    // Calculate number of additional runs needed
    let n = if calib_time > 0.0 {
        let remaining = TARGET_TIME_SECS - calib_time;
        if remaining > 0.0 {
            let additional = (remaining / calib_time).ceil() as u64;
            additional.max(min.saturating_sub(1))
        } else {
            min.saturating_sub(1)
        }
    } else {
        min.saturating_sub(1).max(99)
    };

    // Apply max_runs constraint
    let n = if let Some(max) = max_runs {
        n.min(max.saturating_sub(1))
    } else {
        n
    };

    // Total = calibration run + n additional runs
    // But we need to re-run from scratch since calib was a "test" run
    // Actually the calibration IS the first run, so total_additional = n
    // and we return n (the additional runs after calibration)
    // Wait, but we already ran the calibration. Let me restructure...

    // Actually looking at how hyperfine works:
    // - It does one "initial" run that's NOT counted in the statistics
    // - Then it does ceil(remaining_time / run_time) more runs
    // So total statistical runs = ceil((3.0 - t_init) / t_init) = ceil(3.0/t_init - 1)

    let total_stats_runs = n;
    let total = total_stats_runs.max(min.saturating_sub(1));

    let final_total = if let Some(max) = max_runs {
        total.min(max)
    } else {
        total
    };

    Ok(final_total.max(1))
}

fn run_helper_command(cmd: &str, shell: &Shell) -> Result<(), String> {
    let mut command = build_command(cmd, shell);
    command.stdout(Stdio::null());
    command.stderr(Stdio::null());
    command.stdin(Stdio::null());
    command.spawn()
        .map_err(|e| format!("Failed to run helper command '{}': {}", cmd, e))?
        .wait()
        .map_err(|e| format!("Failed to wait for helper command: {}", e))?;
    Ok(())
}

fn print_benchmark_results(stats: &Stats, args: &Args, use_color: bool) {
    let unit = match &args.time_unit {
        TimeUnit::Auto => determine_unit(stats.mean),
        u => u.clone(),
    };

    let time_str = format_time_line(stats.mean, stats.stddev, stats.user, stats.system, &unit, use_color);
    let range_str = format_range_line(stats.min, stats.max, stats.times.len(), &unit, use_color);

    if use_color {
        println!("  Time ({} \u{b1} {}):{}", 
            colored_bold_green("mean"),
            colored_green("\u{3c3}"),  // σ
            time_str);
        println!("  Range ({} \u{2026} {}):{}", 
            colored_cyan("min"),
            colored_magenta("max"),
            range_str);
    } else {
        println!("  Time (mean \u{b1} \u{3c3}):{}", time_str);
        println!("  Range (min \u{2026} max):{}", range_str);
    }
    println!(" ");

    // Warnings
    if stats.mean < FAST_CMD_THRESHOLD_SECS {
        if use_color {
            println!("  {} Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.", colored_yellow("Warning:"));
        } else {
            println!("  Warning: Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.");
        }
        println!(" ");
    }

    if stats.has_outliers() {
        if use_color {
            println!("  {} Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.", colored_yellow("Warning:"));
        } else {
            println!("  Warning: Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.");
        }
        println!(" ");
    }

    // Check for ignore failure warning
    let has_nonzero = stats.exit_codes.iter().any(|ec| *ec != Some(0));
    if has_nonzero {
        if use_color {
            println!("  {} Ignoring non-zero exit code.", colored_yellow("Warning:"));
        } else {
