fn get_spinner(idx: usize) -> &'static str {
    const FRAMES: &[&str] = &["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
    FRAMES[idx % FRAMES.len()]
}

fn determine_run_count(
    command: &str,
    shell: &Shell,
    output_where: &OutputWhere,
    stdin_src: &InputWhere,
    fixed_runs: Option<u64>,
    min_runs: Option<u64>,
    max_runs: Option<u64>,
    shell_overhead: f64,
) -> Result<u64, String> {
    if let Some(runs) = fixed_runs {
        return Ok(runs);
    }

    let min = min_runs.unwrap_or(DEFAULT_MIN_RUNS);

    // Run one calibration measurement
    let calib_result = time_command(
        command,
        shell,
        &[("HYPERFINE_ITERATION".to_string(), "0".to_string())],
        output_where,
        output_where,
        stdin_src,
        false,
    )?;

    let calib_time = (calib_result.wall_time - shell_overhead).max(0.0);

    // Calculate number of additional runs needed
    let n = if calib_time > 0.0 {
        let remaining = TARGET_TIME_SECS - calib_time;
        if remaining > 0.0 {
            let additional = (remaining / calib_time).ceil() as u64;
            additional.max(min.saturating_sub(1))
        } else {
            min.saturating_sub(1)
        }
    } else {
        min.saturating_sub(1).max(99)
    };

    // Apply max_runs constraint
    let n = if let Some(max) = max_runs {
        n.min(max.saturating_sub(1))
    } else {
        n
    };

    // Total = calibration run + n additional runs
    // But we need to re-run from scratch since calib was a "test" run
    // Actually the calibration IS the first run, so total_additional = n
    // and we return n (the additional runs after calibration)
    // Wait, but we already ran the calibration. Let me restructure...

    // Actually looking at how hyperfine works:
    // - It does one "initial" run that's NOT counted in the statistics
    // - Then it does ceil(remaining_time / run_time) more runs
    // So total statistical runs = ceil((3.0 - t_init) / t_init) = ceil(3.0/t_init - 1)

    let total_stats_runs = n;
    let total = total_stats_runs.max(min.saturating_sub(1));

    let final_total = if let Some(max) = max_runs {
        total.min(max)
    } else {
        total
    };

    Ok(final_total.max(1))
}

fn run_helper_command(cmd: &str, shell: &Shell) -> Result<(), String> {
    let mut command = build_command(cmd, shell);
    command.stdout(Stdio::null());
    command.stderr(Stdio::null());
    command.stdin(Stdio::null());
    command.spawn()
        .map_err(|e| format!("Failed to run helper command '{}': {}", cmd, e))?
        .wait()
        .map_err(|e| format!("Failed to wait for helper command: {}", e))?;
    Ok(())
}

fn print_benchmark_results(stats: &Stats, args: &Args, use_color: bool) {
    let unit = match &args.time_unit {
        TimeUnit::Auto => determine_unit(stats.mean),
        u => u.clone(),
    };

    let time_str = format_time_line(stats.mean, stats.stddev, stats.user, stats.system, &unit, use_color);
    let range_str = format_range_line(stats.min, stats.max, stats.times.len(), &unit, use_color);

    if use_color {
        println!("  Time ({} \u{b1} {}):{}", 
            colored_bold_green("mean"),
            colored_green("\u{3c3}"),  // σ
            time_str);
        println!("  Range ({} \u{2026} {}):{}", 
            colored_cyan("min"),
            colored_magenta("max"),
            range_str);
    } else {
        println!("  Time (mean \u{b1} \u{3c3}):{}", time_str);
        println!("  Range (min \u{2026} max):{}", range_str);
    }
    println!(" ");

    // Warnings
    if stats.mean < FAST_CMD_THRESHOLD_SECS {
        if use_color {
            println!("  {} Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.", colored_yellow("Warning:"));
        } else {
            println!("  Warning: Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.");
        }
        println!(" ");
    }

    if stats.has_outliers() {
        if use_color {
            println!("  {} Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.", colored_yellow("Warning:"));
        } else {
            println!("  Warning: Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.");
        }
        println!(" ");
    }

    // Check for ignore failure warning
    let has_nonzero = stats.exit_codes.iter().any(|ec| *ec != Some(0));
    if has_nonzero {
        if use_color {
            println!("  {} Ignoring non-zero exit code.", colored_yellow("Warning:"));
        } else {
            println!("  Warning: Ignoring non-zero exit code.");
        }
        println!(" ");
    }

    // First run warning
    if let Some(first_time) = stats.first_run_significantly_slower() {
        let unit = match &args.time_unit {
            TimeUnit::Auto => determine_unit(first_time),
            u => u.clone(),
        };
        let time_str = format_compact_time(first_time, &unit);
        if use_color {
            println!("  {} The first benchmarking run for this command was significantly slower than the rest ({}). This could be caused by (filesystem) caches that were not filled until after the first run. You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.", colored_yellow("Warning:"), time_str);
