use crate::benchmark::{BenchmarkResult, BenchmarkSpec, run_benchmark};
use crate::format::*;
use crate::shell::calibrate_shell;
use crate::export::*;
use std::io::{self, IsTerminal, Write};

pub fn run(raw_args: Vec<String>) -> Result<(), String> {
    let args = match crate::args::parse_args(raw_args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            eprintln!();
            eprintln!("Usage: hyperfine [OPTIONS] <command>...");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            std::process::exit(2);
        }
    };

    // Handle missing commands
    if args.commands.is_empty() && args.parameter_scan.is_none() && args.parameter_lists.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <command>...");
        eprintln!();
        eprintln!("Usage: hyperfine <command>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    if args.commands.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <command>...");
        eprintln!();
        eprintln!("Usage: hyperfine <command>...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(2);
    }

    // Determine output style
    let is_tty = io::stdout().is_terminal();
    let (use_color, use_progress) = match &args.style {
        OutputStyle::Auto => (is_tty, is_tty),
        OutputStyle::Basic => (false, false),
        OutputStyle::Full => (true, true),
        OutputStyle::NoColor => (false, true),
        OutputStyle::Color => (true, false),
        OutputStyle::None => return Ok(()),
    };

    // Generate benchmark specs from parameters
    let specs = generate_specs(&args)?;

    if specs.is_empty() {
        return Ok(());
    }

    // Calibrate shell if needed
    let style_is_none = matches!(args.style, OutputStyle::None);
    let shell_overhead = if !matches!(args.shell, Shell::None) {
        calibrate_shell(&args.shell)
    } else {
        0.0
    };

    // Handle --reference: prepend reference command
    let mut all_specs = specs;
    let reference_idx = if let Some(ref_cmd) = &args.reference {
        // Find the reference in the current specs, or create a new one
        let ref_name = args.reference_name.clone().unwrap_or_else(|| ref_cmd.clone());
        let ref_spec = BenchmarkSpec {
            command: ref_cmd.clone(),
            display_name: ref_name,
            prepare: if args.prepare.len() == 1 { args.prepare.get(0).cloned() } 
                     else { None },
            conclude: if args.conclude.len() == 1 { args.conclude.get(0).cloned() }
                      else { None },
            parameters: HashMap::new(),
            output_where: get_output_where(&args, 0),
            input_where: args.input.clone().unwrap_or(InputWhere::Null),
        };
        all_specs.insert(0, ref_spec);
        Some(0usize) // reference is first
    } else {
        None
    };

    let total = all_specs.len();
    let mut results: Vec<BenchmarkResult> = Vec::new();

    for (i, spec) in all_specs.iter().enumerate() {
        match run_benchmark(
            spec,
            &args,
            i,
            total,
            shell_overhead,
            is_tty,
            use_color,
            use_progress,
        ) {
            Ok(result) => results.push(result),
            Err(e) => {
                if !style_is_none {
                    eprintln!("Error: {}", e);
                }
                return Err(e);
            }
        }
    }

    // Print comparison if multiple benchmarks
    if results.len() > 1 && !style_is_none {
        print_comparison(&results, &args, reference_idx, use_color);
    }

    // Export results
    if let Some(json_file) = &args.export_json {
        let json = export_json(&results);
        std::fs::write(json_file, json)
            .map_err(|e| format!("Failed to write JSON: {}", e))?;
    }

    if let Some(csv_file) = &args.export_csv {
        let csv = export_csv(&results);
        std::fs::write(csv_file, csv)
            .map_err(|e| format!("Failed to write CSV: {}", e))?;
    }

    if let Some(md_file) = &args.export_markdown {
        let md = export_markdown(&results, &args.time_unit, &args.sort, reference_idx);
        std::fs::write(md_file, md)
            .map_err(|e| format!("Failed to write Markdown: {}", e))?;
    }

    if let Some(adoc_file) = &args.export_asciidoc {
        let adoc = export_asciidoc(&results, &args.time_unit, &args.sort, reference_idx);
        std::fs::write(adoc_file, adoc)
            .map_err(|e| format!("Failed to write AsciiDoc: {}", e))?;
    }

    if let Some(org_file) = &args.export_orgmode {
        let org = export_orgmode(&results, &args.time_unit, &args.sort, reference_idx);
        std::fs::write(org_file, org)
            .map_err(|e| format!("Failed to write org-mode: {}", e))?;
    }

    Ok(())
}

fn generate_specs(args: &Args) -> Result<Vec<BenchmarkSpec>, String> {
    let mut specs = Vec::new();

    // Generate parameter combinations
    let param_combinations = generate_param_combinations(args);

    for (cmd_idx, command) in args.commands.iter().enumerate() {
        let display_name = args.command_names.get(cmd_idx)
            .map(|n| n.clone());

        if param_combinations.is_empty() {
            let name = display_name.unwrap_or_else(|| command.clone());
            let output = get_output_where(args, cmd_idx);
            let input = args.input.clone().unwrap_or(InputWhere::Null);
            let prepare = get_prepare(args, cmd_idx);
            let conclude = get_conclude(args, cmd_idx);

            specs.push(BenchmarkSpec {
                command: command.clone(),
                display_name: name,
                prepare,
                conclude,
                parameters: HashMap::new(),
                output_where: output,
                input_where: input,
            });
        } else {
            for params in &param_combinations {
                // Substitute parameters in command
                let mut substituted_cmd = command.clone();
                for (var, val) in params {
                    substituted_cmd = substituted_cmd.replace(&format!("{{{}}}", var), val);
                }

                // Generate display name
                let name = if let Some(dn) = &display_name {
                    let mut substituted = dn.clone();
                    for (var, val) in params {
                        substituted = substituted.replace(&format!("{{{}}}", var), val);
                    }
                    substituted
                } else {
                    // Use substituted command as name
                    // Add parameter labels for unsubstituted params
                    let mut extra_params: Vec<(String, String)> = Vec::new();
                    for (var, val) in params {
                        if !command.contains(&format!("{{{}}}", var)) {
                            extra_params.push((var.clone(), val.clone()));
                        }
                    }
                    if extra_params.is_empty() {
                        substituted_cmd.clone()
                    } else {
                        let param_str = extra_params.iter()
                            .map(|(k, v)| format!("{} = {}", k, v))
                            .collect::<Vec<_>>()
                            .join(", ");
                        format!("{} ({param_str})", substituted_cmd)
                    }
                };

                let output = get_output_where(args, cmd_idx);
                let input = args.input.clone().unwrap_or(InputWhere::Null);
                let prepare = get_prepare(args, cmd_idx);
                let conclude = get_conclude(args, cmd_idx);

                specs.push(BenchmarkSpec {
                    command: substituted_cmd,
                    display_name: name,
                    prepare,
                    conclude,
                    parameters: params.clone(),
                    output_where: output,
                    input_where: input,
                });
            }
        }
    }

    Ok(specs)
}

fn generate_param_combinations(args: &Args) -> Vec<HashMap<String, String>> {
    let mut combinations: Vec<HashMap<String, String>> = Vec::new();

    // Start with parameter scan
    if let Some(scan) = &args.parameter_scan {
        let step = scan.step.unwrap_or(1.0);
        let mut val = scan.min;
        let mut scan_values: Vec<String> = Vec::new();

        while val <= scan.max + step * 1e-10 {
            // Format the value with appropriate precision
            let formatted = format_scan_value(val, step);
            scan_values.push(formatted);
            val += step;
        }

        combinations = scan_values.into_iter()
            .map(|v| {
                let mut m = HashMap::new();
                m.insert(scan.var.clone(), v);
                m
            })
            .collect();
    }

    // Add parameter lists
    for plist in &args.parameter_lists {
        if combinations.is_empty() {
            combinations = plist.values.iter()
                .map(|v| {
                    let mut m = HashMap::new();
                    m.insert(plist.var.clone(), v.clone());
                    m
                })
                .collect();
        } else {
            let mut new_combinations = Vec::new();
            for existing in &combinations {
                for val in &plist.values {
                    let mut new = existing.clone();
                    new.insert(plist.var.clone(), val.clone());
                    new_combinations.push(new);
                }
            }
            combinations = new_combinations;
        }
    }

    combinations
}

fn format_scan_value(val: f64, step: f64) -> String {
    // Determine decimal places needed
    if step == step.floor() && val == val.floor() {
        // Both are integers
        format!("{}", val as i64)
    } else {
        // Determine precision from step
        let step_str = format!("{}", step);
        let decimals = if let Some(dot_pos) = step_str.find('.') {
            step_str.len() - dot_pos - 1
        } else {
            0
        };
        // Also check val itself
        let val_str = format!("{}", val);
        let val_decimals = if let Some(dot_pos) = val_str.find('.') {
            val_str.len() - dot_pos - 1
        } else {
            0
        };
        let prec = decimals.max(val_decimals);
        format!("{:.prec$}", val, prec = prec)
    }
}

fn get_output_where(args: &Args, idx: usize) -> OutputWhere {
    if args.show_output {
        return OutputWhere::Inherit;
    }
    if args.output.is_empty() {
        OutputWhere::Null
    } else if args.output.len() == 1 {
        args.output[0].clone()
    } else {
        args.output.get(idx).cloned().unwrap_or(OutputWhere::Null)
    }
}

fn get_prepare(args: &Args, idx: usize) -> Option<String> {
    if args.prepare.is_empty() {
        None
    } else if args.prepare.len() == 1 {
        args.prepare.get(0).cloned()
    } else {
        args.prepare.get(idx).cloned()
    }
}

fn get_conclude(args: &Args, idx: usize) -> Option<String> {
    if args.conclude.is_empty() {
        None
    } else if args.conclude.len() == 1 {
        args.conclude.get(0).cloned()
    } else {
        args.conclude.get(idx).cloned()
    }
}

fn print_comparison(
    results: &[BenchmarkResult],
    args: &Args,
    reference_idx: Option<usize>,
    use_color: bool,
) {
    // Check if all times are zero
    let all_zero = results.iter().all(|r| r.stats.mean == 0.0);
    if all_zero {
        println!("Note: The benchmark comparison could not be computed as some benchmark times are zero. This could be caused by background interference during the initial calibration phase of hyperfine, in combination with very fast commands (faster than a few milliseconds). Try to re-run the benchmark on a quiet system. If you did not do so already, try the --shell=none/-N option. If it does not help either, you command is most likely too fast to be accurately benchmarked by hyperfine.");
        return;
    }

    // Check if any time is zero
    let any_zero = results.iter().any(|r| r.stats.mean == 0.0);
    if any_zero {
        println!("Note: The benchmark comparison could not be computed as some benchmark times are zero. This could be caused by background interference during the initial calibration phase of hyperfine, in combination with very fast commands (faster than a few milliseconds). Try to re-run the benchmark on a quiet system. If you did not do so already, try the --shell=none/-N option. If it does not help either, you command is most likely too fast to be accurately benchmarked by hyperfine.");
        return;
    }

    match &args.sort {
        SortOrder::Command => {
            // "Relative speed comparison" format - keep original order
            print_relative_comparison(results, args, reference_idx, use_color);
        }
        _ => {
            // "Summary" format - fastest first
            print_summary_comparison(results, args, reference_idx, use_color);
        }
    }
}

fn get_reference_idx(results: &[BenchmarkResult], reference_idx: Option<usize>) -> usize {
    reference_idx.unwrap_or_else(|| {
        results.iter().enumerate()
            .min_by(|(_, a), (_, b)| a.stats.mean.partial_cmp(&b.stats.mean).unwrap())
            .map(|(i, _)| i)
            .unwrap_or(0)
    })
}

fn print_summary_comparison(
    results: &[BenchmarkResult],
    args: &Args,
    reference_idx: Option<usize>,
    use_color: bool,
) {
    let ref_idx = get_reference_idx(results, reference_idx);
    let ref_result = &results[ref_idx];

    // Sort other results by mean time (ascending)
    let mut other_indices: Vec<usize> = (0..results.len())
        .filter(|&i| i != ref_idx)
        .collect();

    if reference_idx.is_none() {
        // Sort by mean time
        other_indices.sort_by(|&a, &b| {
            results[a].stats.mean.partial_cmp(&results[b].stats.mean).unwrap()
        });
    }
    // If reference_idx is Some (explicit reference), keep original order of others

    if use_color {
        println!("Summary");
    } else {
        println!("Summary");
    }

    let ref_name = if use_color {
        format!("\x1b[1;32m{}\x1b[0m", ref_result.display_name)
    } else {
        ref_result.display_name.clone()
    };

    println!("  {} ran", ref_name);

    for &other_idx in &other_indices {
        let other = &results[other_idx];
        let ratio = other.stats.mean / ref_result.stats.mean;

        // Error propagation
        let sigma = if ref_result.stats.mean > 0.0 && other.stats.mean > 0.0 {
            ratio * ((other.stats.stddev / other.stats.mean).powi(2) + 
                     (ref_result.stats.stddev / ref_result.stats.mean).powi(2)).sqrt()
        } else {
            0.0
        };

        let ratio_str = format!("{:.2}", ratio);
        let sigma_str = format!("{:.2}", sigma);

        let other_name = if use_color {
            format!("\x1b[1;32m{}\x1b[0m", other.display_name)
        } else {
            other.display_name.clone()
        };

        let (faster_or_slower, ratio_val, sigma_val) = if reference_idx.is_some() {
            // With explicit reference: compare reference to others
            // ratio = other_time / ref_time
            if ratio > 1.0 {
                // reference is faster than other
                ("faster than", ratio, sigma)
            } else if ratio < 1.0 {
                // reference is slower than other
                ("slower than", 1.0 / ratio, 
                 (1.0/ratio) * ((ref_result.stats.stddev / ref_result.stats.mean).powi(2) + 
                               (other.stats.stddev / other.stats.mean).powi(2)).sqrt())
            } else {
                ("faster than", ratio, sigma)
            }
        } else {
            ("faster than", ratio, sigma)
        };

        let ratio_formatted = format!("{:>8.2}", ratio_val);
        let sigma_formatted = format!("{:.2}", sigma_val);

        let comparison = if use_color {
            format!("    {} \u{b1} {} times {} {}",
                format!("{:>8}", format!("{:.2}", ratio_val)),
                sigma_formatted,
                faster_or_slower,
                other_name)
        } else {
            format!("    {} \u{b1} {} times {} {}",
                format!("{:>8}", format!("{:.2}", ratio_val)),
                sigma_formatted,
                faster_or_slower,
                other_name)
        };

        println!("{}", comparison);
    }
}

fn print_relative_comparison(
    results: &[BenchmarkResult],
    args: &Args,
    reference_idx: Option<usize>,
    use_color: bool,
) {
    let ref_idx = get_reference_idx(results, reference_idx);
    let ref_result = &results[ref_idx];

    println!("Relative speed comparison");

    for (i, result) in results.iter().enumerate() {
        let ratio = if ref_result.stats.mean > 0.0 {
            result.stats.mean / ref_result.stats.mean
        } else {
            1.0
        };

        let sigma = if i == ref_idx {
            0.0
        } else if ref_result.stats.mean > 0.0 && result.stats.mean > 0.0 {
            ratio * ((result.stats.stddev / result.stats.mean).powi(2) + 
                     (ref_result.stats.stddev / ref_result.stats.mean).powi(2)).sqrt()
        } else {
            0.0
        };

        let ratio_str = format!("{:>12.2}", ratio);

        let line = if i == ref_idx {
            // No sigma for reference
            format!("{}          {}", ratio_str, result.display_name)
        } else {
            format!("{} \u{b1} {:>6.2}  {}", ratio_str, sigma, result.display_name)
        };

        println!("{}", line);
    }
}
