    let unit = match &args.time_unit {
        TimeUnit::Auto => determine_unit(stats.mean),
        u => u.clone(),
    };

    let time_str = format_time_line(stats.mean, stats.stddev, stats.user, stats.system, &unit, use_color);
    let range_str = format_range_line(stats.min, stats.max, stats.times.len(), &unit, use_color);

    if use_color {
        println!("  Time ({} \\u{{b1}} {}):{}", 
            colored_bold_green("mean"),
            colored_green("\\u{3c3}"),  // sigma
            time_str);
        println!("  Range ({} \\u{{2026}} {}):{}", 
            colored_cyan("min"),
            colored_magenta("max"),
            range_str);
    } else {
        println!("  Time (mean \\u{{b1}} \\u{{3c3}}):{}", time_str);
        println!("  Range (min \\u{{2026}} max):{}", range_str);
    }
    println!(" ");

    // Collect warnings
    let mut warnings: Vec<String> = Vec::new();

    // Fast command warning
    if stats.mean < FAST_CMD_THRESHOLD_SECS {
        let msg = "Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.";
        if use_color {
            warnings.push(format!("  {} {}", colored_yellow("Warning:"), msg));
        } else {
            warnings.push(format!("  Warning: {}", msg));
        }
    }

    // Outlier warning
    if stats.has_outliers() {
        let msg = "Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.";
        if use_color {
            warnings.push(format!("  {} {}", colored_yellow("Warning:"), msg));
        } else {
            warnings.push(format!("  Warning: {}", msg));
        }
    }

    // Ignore failure warning
    let has_nonzero = stats.exit_codes.iter().any(|ec| *ec != Some(0));
    if has_nonzero {
        let msg = "Ignoring non-zero exit code.";
        if use_color {
            warnings.push(format!("  {} {}", colored_yellow("Warning:"), msg));
        } else {
            warnings.push(format!("  Warning: {}", msg));
        }
    }

    // First run warning
    if let Some(first_time) = stats.first_run_significantly_slower() {
        let first_unit = match &args.time_unit {
            TimeUnit::Auto => determine_unit(first_time),
            u => u.clone(),
        };
        let time_str = format_compact_time(first_time, &first_unit);
        let msg = format!("The first benchmarking run for this command was significantly slower than the rest ({}). This could be caused by (filesystem) caches that were not filled until after the first run. You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.", time_str);
        if use_color {
            warnings.push(format!("  {} {}", colored_yellow("Warning:"), msg));
        } else {
            warnings.push(format!("  Warning: {}", msg));
        }
    }

    // Print all warnings, then one blank line if any
    if !warnings.is_empty() {
        for w in &warnings {
            println!("{}", w);
        }
        println!(" ");
    }
}'''

