                let inv_ratio = 1.0 / ratio;
                let inv_sigma = inv_ratio * ((ref_result.stats.stddev / ref_result.stats.mean).powi(2) + 
                               (other.stats.stddev / other.stats.mean).powi(2)).sqrt();
