            let other_name_colored = format!("\\x1b[35m{}\\x1b[0m", other.display_name);  // magenta
            println!("\\x1b[1;32m{}\\x1b[0m \\u{{b1}} \\x1b[32m{}\\x1b[0m times {} {}",
